 39	public class AbfsListStatusRemoteIterator
 40	    implements RemoteIterator<FileStatus> {
 41	
 42	  private static final Logger LOG = LoggerFactory
 43	      .getLogger(AbfsListStatusRemoteIterator.class);
 44	
 45	  private static final boolean FETCH_ALL_FALSE = false;
 46	  private static final int MAX_QUEUE_SIZE = 10;
 47	  private static final long POLL_WAIT_TIME_IN_MS = 250;
 48	
 49	  private final FileStatus fileStatus;
 50	  private final ListingSupport listingSupport;
 51	  private final ArrayBlockingQueue<Object> iteratorsQueue;
 52	  private final TracingContext tracingContext;
 53	
 54	  private volatile boolean isAsyncInProgress = false;
 55	  private boolean isIterationComplete = false;
 56	  private String continuation;
 57	  private Iterator<FileStatus> currIterator;
 58	
 59	  public AbfsListStatusRemoteIterator(final FileStatus fileStatus,
 60	      final ListingSupport listingSupport, TracingContext tracingContext) {
 61	    this.fileStatus = fileStatus;
 62	    this.listingSupport = listingSupport;
 63	    this.tracingContext = tracingContext;
 64	    iteratorsQueue = new ArrayBlockingQueue<>(MAX_QUEUE_SIZE);
 65	    currIterator = Collections.emptyIterator();
 66	    fetchBatchesAsync();
 67	  }
 68	
 69	  @Override
 70	  public boolean hasNext() throws IOException {
 71	    if (currIterator.hasNext()) {
 72	      return true;
 73	    }
 74	    currIterator = getNextIterator();
 75	    return currIterator.hasNext();
 76	  }
 77	
 78	  @Override
 79	  public FileStatus next() throws IOException {
 80	    if (!this.hasNext()) {
 81	      throw new NoSuchElementException();
 82	    }
 83	    return currIterator.next();
 84	  }
 85	
 86	  private Iterator<FileStatus> getNextIterator() throws IOException {
 87	    fetchBatchesAsync();
 88	    try {
 89	      Object obj = null;
 90	      while (obj == null
 91	          && (!isIterationComplete || !iteratorsQueue.isEmpty())) {
 92	        obj = iteratorsQueue.poll(POLL_WAIT_TIME_IN_MS, TimeUnit.MILLISECONDS);
 93	      }
 94	      if (obj == null) {
 95	        return Collections.emptyIterator();
 96	      } else if (obj instanceof Iterator) {
 97	        return (Iterator<FileStatus>) obj;
 98	      } else if (obj instanceof IOException) {
 99	        throw (IOException) obj;
100	      } else {
101	        throw new UnsupportedDataTypeException();
102	      }
103	    } catch (InterruptedException e) {
104	      Thread.currentThread().interrupt();
105	      LOG.error("Thread got interrupted: {}", e);
106	      throw new IOException(e);
107	    }
108	  }
109	
110	  private void fetchBatchesAsync() {
111	    if (isAsyncInProgress || isIterationComplete) {
112	      return;
113	    }
114	    synchronized (this) {
115	      if (isAsyncInProgress || isIterationComplete) {
116	        return;
117	      }
118	      isAsyncInProgress = true;
119	    }
120	    CompletableFuture.runAsync(() -> asyncOp());
121	  }
122	
123	  private void asyncOp() {
124	    try {
125	      while (!isIterationComplete && iteratorsQueue.size() <= MAX_QUEUE_SIZE) {
126	        addNextBatchIteratorToQueue();
127	      }
128	    } catch (IOException ioe) {
129	      LOG.error("Fetching filestatuses failed", ioe);
130	      try {
131	        iteratorsQueue.put(ioe);
132	      } catch (InterruptedException interruptedException) {
133	        Thread.currentThread().interrupt();
134	        LOG.error("Thread got interrupted: {}", interruptedException);
135	      }
136	    } catch (InterruptedException e) {
137	      Thread.currentThread().interrupt();
138	      LOG.error("Thread got interrupted: {}", e);
139	    } finally {
140	      synchronized (this) {
141	        isAsyncInProgress = false;
142	      }
143	    }
144	  }
145	
146	  private void addNextBatchIteratorToQueue()
147	      throws IOException, InterruptedException {
148	    List<FileStatus> fileStatuses = new ArrayList<>();
149	    continuation = listingSupport
150	        .listStatus(fileStatus.getPath(), null, fileStatuses, FETCH_ALL_FALSE,
151	            continuation, tracingContext);
152	    if (!fileStatuses.isEmpty()) {
153	      iteratorsQueue.put(fileStatuses.iterator());
154	    }
155	    synchronized (this) {
156	      if (continuation == null || continuation.isEmpty()) {
157	        isIterationComplete = true;
158	      }
159	    }
160	  }
161	
162	}

