 59	  @Test
 60	  public void testAbfsIteratorWithHasNext() throws Exception {
 61	    Path testDir = createTestDirectory();
 62	    setPageSize(10);
 63	    final List<String> fileNames = createFilesUnderDirectory(TEST_FILES_NUMBER,
 64	        testDir, "testListPath");
 65	
 66	    ListingSupport listngSupport = Mockito.spy(getFileSystem().getAbfsStore());
 67	    RemoteIterator<FileStatus> fsItr = new AbfsListStatusRemoteIterator(
 68	        getFileSystem().getFileStatus(testDir), listngSupport,
 69	        getTestTracingContext(getFileSystem(), true));
 70	    Assertions.assertThat(fsItr)
 71	        .describedAs("RemoteIterator should be instance of "
 72	            + "AbfsListStatusRemoteIterator by default")
 73	        .isInstanceOf(AbfsListStatusRemoteIterator.class);
 74	    int itrCount = 0;
 75	    while (fsItr.hasNext()) {
 76	      FileStatus fileStatus = fsItr.next();
 77	      String pathStr = fileStatus.getPath().toString();
 78	      fileNames.remove(pathStr);
 79	      itrCount++;
 80	    }
 81	    Assertions.assertThat(itrCount)
 82	        .describedAs("Number of iterations should be equal to the files "
 83	            + "created")
 84	        .isEqualTo(TEST_FILES_NUMBER);
 85	    Assertions.assertThat(fileNames.size())
 86	        .describedAs("After removing every iterm found from the iterator, "
 87	            + "there should be no more elements in the fileNames")
 88	        .isEqualTo(0);
 89	    int minNumberOfInvokations = TEST_FILES_NUMBER / 10;
 90	    verify(listngSupport, Mockito.atLeast(minNumberOfInvokations))
 91	        .listStatus(any(Path.class), nullable(String.class),
 92	            anyList(), anyBoolean(),
 93	            nullable(String.class),
 94	            any(TracingContext.class));
 95	  }
